S('0239',"تعليمات منح درجة البكالوريوس لطلبة برنامج البكالوريوس الإضافي",[
("number",[1],"المادة 4","يقبل الطالب في برنامج البكالوريوس الإضافي للحصول على درجة البكالوريوس وفق الشروط التالية: أن يكون الطالب حاصلاً على درجة البكالوريوس أو ما يعادلها من جامعة أو معهد جامعي أو كلية جامعية تعترف بها الجامعة، وألا يكون قد مضى على حصوله على درجة البكالوريوس الأولى أكثر من 7 سنوات، وأن يحقق الشروط الأخرى التي تضعها كل كلية للقبول فيها، وأن يقدم طلبات الالتحاق الكترونياً.",
 "ما شروط القبول في برنامج البكالوريوس الإضافي؟","كم المدة القصوى بين الحصول على البكالوريوس الأولى والالتحاق ببرنامج البكالوريوس الإضافي؟","شو شروط القبول ببرنامج البكالوريوس الإضافي؟"),
("number",[1],"المادة 6","إذا تخرج الطالب من الجامعة وقبل في برنامج البكالوريوس الإضافي تطبق عليه تعليمات احتساب المساقات من داخل الجامعة، ولا تدخل نتائج هذه المساقات في حساب معدله التراكمي (تدخل العلامة كمساق معفى)، ويحسم فصل دراسي واحد من الحد الأعلى لمدة الدراسة مقابل كل (15) ساعة معتمدة تحسب للطالب. ولا يجوز للطالب احتساب ساعات معتمدة أتمها بنجاح في جامعة أخرى بعد التحاقه بالجامعة إلا إذا كان التسجيل بموافقة مسبقة من عميد الكلية المختص.",
 "هل تدخل علامات المساقات المحتسبة في المعدل التراكمي لطالب البكالوريوس الإضافي؟","كم ساعة معتمدة يحسم مقابلها فصل دراسي من مدة الدراسة لطالب البكالوريوس الإضافي؟","ماذا يحدث لمساقاتي القديمة إذا قبلت بالبكالوريوس الإضافي؟"),
("rule",[1],"المادة 7","تستوفى من الطلبة المقبولين في برنامج البكالوريوس الإضافي نفس الرسوم الجامعية التي يدفعها طلبة البرنامج الدراسي الموازي أو الدولي حسب التخصص والجنسية ضمن أسس القبول المعمول بها في الجامعة.",
 "ما الرسوم التي يدفعها طلبة البكالوريوس الإضافي؟","هل رسوم البكالوريوس الإضافي مثل الموازي؟","كم رسوم البكالوريوس الإضافي؟"),
])

S('0246',"أسس قبول الطلبة المتفوقين علمياً وبحثياً في جامعة العلوم والتكنولوجيا الأردنية",[
("rule",[1],"المادة 2 و3 و4","تطبق أسس القبول للمتفوقين علمياً وبحثياً على الطلبة الأردنيين الحاصلين على شهادة الدراسة الثانوية العامة أو ما يعادلها، بشرط ألا يقل معدلهم عن الحد الأدنى لمعدلات الالتحاق الواردة في أسس القبول للطلبة في الجامعات الأردنية الرسمية، ويتم قبول الطلبة في جميع التخصصات باستثناء تخصصي الطب والجراحة وطب وجراحة الأسنان.",
 "على من تطبق أسس قبول الطلبة المتفوقين علمياً وبحثياً؟","هل يقبل المتفوقون علمياً وبحثياً في الطب وطب الأسنان؟","هل بقدر أقبل بالطب كمتفوق علمي أو بحثي؟"),
("rule",[1],"المادة 5","يعتبر الطالب متفوقاً علمياً وبحثياً إذا حصل على جائزة في مسابقة علمية أو بحثية على المستوى العالمي أو على جائزة في مسابقة علمية أو بحثية على المستوى الإقليمي، وعلى الطالب المتقدم للقبول أن يقدم شهادة تثبت حصوله على الجائزة.",
 "متى يعتبر الطالب متفوقاً علمياً وبحثياً؟","ما الوثيقة المطلوبة لإثبات التفوق العلمي والبحثي؟","شو لازم أقدم عشان أنقبل كمتفوق علمي؟"),
("number",[1],"المادة 10 و12","تختار اللجنة الطلبة الذين تنطبق عليهم شروط التفوق العلمي والبحثي في ضوء المعايير التالية: معدل الطالب في امتحان الثانوية العامة ويخصص له 50 علامة، ومستوى الجائزة العلمية أو البحثية (الجائزة العالمية 40 علامة والجائزة الإقليمية 30 علامة)، ومقابلة اللجنة وتخصص لها 10 علامات، ويتم القبول تنافسياً حسب مجموع العلامات أعلاه. ويصدر رئيس الجامعة قراراً بقبول الطلبة بما لا يتجاوز عشر طلاب في العام الجامعي الواحد.",
 "كم علامة يخصص لمعدل الثانوية العامة في قبول المتفوقين علمياً وبحثياً؟","كم علامة للجائزة العالمية وللجائزة الإقليمية في القبول؟","كم أقصى عدد طلاب يقبلون سنوياً كمتفوقين علمياً وبحثياً؟"),
("rule",[1],"المادة 9","يشكل رئيس الجامعة لجنة على النحو التالي لاختبار قدرات الطلبة: عميد البحث العلمي رئيساً، وعميد شؤون الطلبة عضواً، ومدير القبول والتسجيل عضواً، وعضو هيئة تدريس من الكليات العلمية بالجامعة.",
 "من يتألف منهم لجنة اختبار قدرات الطلبة المتفوقين علمياً وبحثياً؟","من يرأس لجنة قبول المتفوقين علمياً وبحثياً؟","مين بكون بلجنة قبول المتفوقين علمياً؟"),
])

S('0249',"تعليمات منح درجة الدبلوم المتوسط التقني ضمن برامج البكالوريوس التقني",[
("number",[1],"المادة 5","الحد الأدنى لعدد الساعات للحصول على درجة الدبلوم المتوسط التقني (72) ساعة معتمدة (البرنامج ذو السنتين)، و(96) ساعة معتمدة (البرنامج ذو الثلاث سنوات).",
 "كم الحد الأدنى للساعات المعتمدة للحصول على درجة الدبلوم المتوسط التقني؟","كم ساعة معتمدة في برنامج الدبلوم التقني ذي الثلاث سنوات؟","كم ساعة بدي أخلص للدبلوم التقني؟"),
("number",[1],"المادة 5","تتوزع ساعات الدبلوم المتوسط التقني على: متطلبات الثقافة العامة (6) ساعات معتمدة، ومتطلبات مهارات التشغيل (9–12) ساعة، ومتطلبات العلوم الأساسية للمؤهل (6–9) ساعات، والممارسة المهنية (6) ساعات معتمدة (برنامج السنتين) و(12) ساعة (برنامج الثلاث سنوات) إلزامية في مواقع التدريب المعتمدة، ومتطلبات التخصص (39–45) ساعة (برنامج السنتين) و(57–63) ساعة (برنامج الثلاث سنوات).",
 "كم ساعة لمتطلبات الثقافة العامة في الدبلوم المتوسط التقني؟","كم ساعة للممارسة المهنية في برنامج الدبلوم التقني ذي السنتين؟","كيف بتتوزع ساعات الدبلوم التقني؟"),
("number",[1],"المادة 8","تمنح درجة الدبلوم المتوسط التقني للطالب بعد إتمام المتطلبات التالية: النجاح في جميع المساقات اللازمة لتحقيق متطلبات نقطة الخروج حسب الخطة الدراسية المعتمدة، والحصول على معدل تراكمي لا يقل عن (2.00) في المساقات المشمولة في البند (1)، وفي حال تم معادلة مساقات من خارج الجامعة يجب أن لا يقل عدد الساعات المعتمدة التي أتم الطالب دراستها بنجاح في الجامعة عن 50% من مجموع الساعات اللازمة لتحقيق متطلبات نقطة الخروج.",
 "ما شروط منح درجة الدبلوم المتوسط التقني؟","كم أدنى معدل تراكمي للحصول على الدبلوم المتوسط التقني؟","شو لازم أحقق عشان آخذ الدبلوم التقني؟"),
("rule",[1],"المادة 6 و7 و9","يجوز للطالب الذي استوفى متطلبات الحصول على درجة الدبلوم المتوسط التقني التقدم بطلب لوحدة القبول والتسجيل للحصول على الدرجة، ويجوز للطالب استكمال دراسته والاستمرار في برنامج البكالوريوس التقني الملتحق به بعد الحصول على الدبلوم. ويصدر قرار منح الدرجة من المجلس بناء على تنسيب من مجلس الكلية المعني.",
 "هل يمكن للطالب الاستمرار بالبكالوريوس التقني بعد الحصول على الدبلوم المتوسط؟","من يصدر قرار منح درجة الدبلوم المتوسط التقني؟","بقدر أكمل بكالوريوس تقني بعد الدبلوم؟"),
])

S('0230',"تعهد الطالب بخصوص الامتحانات في جامعة العلوم والتكنولوجيا الأردنية",[
("number",[1],"البند 1","على الطالب الوصول مبكراً إلى قاعة الامتحان، ولا يسمح للطالب المتأخر بدخول قاعة الامتحان بعد مضي أكثر من 25% من الزمن المخصص للامتحان.",
 "إلى متى يسمح للطالب المتأخر بدخول قاعة الامتحان؟","هل يسمح بدخول قاعة الامتحان بعد مضي نصف الوقت؟","كم بقدر أتأخر عن الامتحان وأدخل؟"),
("rule",[1],"البند 2","لا يسمح للطالب بإدخال أي من التالي إلى قاعة الامتحان (إلا المواد المصرح بها مسبقاً): الهاتف المحمول، والآلات الحاسبة، وسماعات الأذن غير الطبية، والساعات الذكية والأقلام الذكية، والحواسيب والأجهزة اللوحية، وأي أجهزة إلكترونية أخرى، وكاميرات من كل نوع، والكتب والأوراق والملفات، والحقائب والمتعلقات الشخصية غير اللازمة للامتحان. ويوضع ما يلزم إحضاره منها في مقدمة القاعة والجامعة غير مسؤولة عن أي تلف أو ضياع، ويعتبر وجود أي مادة غير مصرح بها محاولة غش.",
 "ما الأشياء الممنوع إدخالها إلى قاعة الامتحان؟","هل الجامعة مسؤولة عن ضياع الأغراض التي توضع في مقدمة قاعة الامتحان؟","شو الممنوع أدخله على قاعة الامتحان؟"),
("rule",[1],"البنود 3 إلى 5","على الطالب الجلوس في المقعد المحدد والالتزام بتعليمات المراقبين، وإحضار هويته الجامعية ووضعها بشكل ظاهر على طاولته، ولا يسمح له بمغادرة قاعة الامتحان قبل مضي نصف الوقت المخصص للامتحان.",
 "متى يسمح للطالب بمغادرة قاعة الامتحان؟","أين يضع الطالب هويته الجامعية في الامتحان؟","بقدر أطلع من الامتحان بأي وقت؟"),
("rule",[1],"البند 9 و10","لا يسمح للطالب في قاعة الامتحان بالحديث أو الكلام مع الطلبة الآخرين أو محاولة رؤية ما يكتبونه، ولا تبادل أي أوراق أو أدوات من أي نوع، ولا إظهار ورقة الامتحان لطالب آخر عمداً، ولا النظر إلى أوراق الآخرين، ويعتبر مخالفة ذلك غشاً تطبق بحقه العقوبات التأديبية، وعلى الطالب تسليم جميع الأوراق للمراقبين بما فيها ورقة الأسئلة ومسودات الملاحظات قبل مغادرة القاعة. ويشترط توقيع نموذج التعهد ليتمكن الطالب من دخول الامتحانات.",
 "ما الأفعال المحظورة على الطالب داخل قاعة الامتحان؟","هل يجب توقيع نموذج التعهد للسماح بدخول الامتحان؟","شو لازم أسلم للمراقب قبل ما أطلع من الامتحان؟"),
],'text')
